import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1787084291000}'),s={name:"guide/faq.md"};function i(n,e,l,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to &quot;FAQ &amp; troubleshooting&quot;">​</a></h1><h2 id="why-do-my-routes-differ-from-google-maps" tabindex="-1">Why do my routes differ from Google Maps? <a class="header-anchor" href="#why-do-my-routes-differ-from-google-maps" aria-label="Permalink to &quot;Why do my routes differ from Google Maps?&quot;">​</a></h2><p>Different map, different engine, different assumptions:</p><ul><li><strong>The data is OpenStreetMap</strong>, not Google&#39;s. In most of Europe OSM is excellent and often more detailed for footpaths and cycleways; elsewhere coverage varies. A missing path in OSM means a longer route here.</li><li><strong>No live traffic.</strong> OSRM computes travel times from road classes and speed profiles, not congestion feeds. Car times are free-flow estimates — expect them to be optimistic in city rush hour and pretty accurate at night.</li><li><strong>Different cost models.</strong> Every router weighs turns, road classes and surfaces its own way. Two correct engines routinely disagree by a few percent on the same map.</li></ul><p>Treat differences of a few minutes as normal. A <em>walking</em> route that matches a <em>driving</em> route suspiciously well is the one failure mode worth reporting — see the next question.</p><h2 id="why-do-walking-routes-need-the-fossgis-routed-prefixes" tabindex="-1">Why do walking routes need the FOSSGIS <code>routed-*</code> prefixes? <a class="header-anchor" href="#why-do-walking-routes-need-the-fossgis-routed-prefixes" aria-label="Permalink to &quot;Why do walking routes need the FOSSGIS `routed-*` prefixes?&quot;">​</a></h2><p>Because the public OSRM demo servers only run <strong>one routing profile per instance</strong>, and the profile segment inside the classic OSRM URL (<code>/route/v1/foot/…</code>) is <strong>ignored</strong> — whatever you write there, a plain OSRM instance answers with the profile it was started with, which on most deployments is <em>car</em>.</p><p>The FOSSGIS servers at <code>routing.openstreetmap.de</code> run three OSRM instances and select between them with a <em>path prefix</em>: <code>/routed-foot/…</code>, <code>/routed-bike/…</code>, <code>/routed-car/…</code>. Skip the prefix and you silently get car routes for every &quot;walking&quot; query — a bug several OSM MCP servers have shipped. This server always sends the prefix, and its live smoke test asserts that a foot route is much slower than the same route by car, so a regression cannot land quietly.</p><p>If you set <code>OSRM_BASE_URL</code> to your own instance, it must serve the same prefixes (three profile instances behind one host).</p><h2 id="is-it-ok-to-point-this-at-the-public-servers-what-are-the-limits" tabindex="-1">Is it OK to point this at the public servers? What are the limits? <a class="header-anchor" href="#is-it-ok-to-point-this-at-the-public-servers-what-are-the-limits" aria-label="Permalink to &quot;Is it OK to point this at the public servers? What are the limits?&quot;">​</a></h2><p>Yes, for <strong>light, non-commercial use</strong> — that is what the operators offer, and the server enforces their published policies client-side so you do not have to think about them:</p><ul><li><strong>Nominatim:</strong> max 1 request/second, identifying User-Agent, results cached (<a href="https://operations.osmfoundation.org/policies/nominatim/" target="_blank" rel="noreferrer">policy</a>).</li><li><strong>OSRM / Valhalla (FOSSGIS):</strong> reasonable, non-commercial use, max 1 request/second (<a href="https://routing.openstreetmap.de/about.html" target="_blank" rel="noreferrer">about</a>).</li><li><strong>Overpass:</strong> ~2 concurrent slots per IP, fewer than 10 000 queries/day (<a href="https://wiki.openstreetmap.org/wiki/Overpass_API" target="_blank" rel="noreferrer">wiki</a>).</li><li><strong>Photon:</strong> fair use (<a href="https://photon.komoot.io" target="_blank" rel="noreferrer">photon.komoot.io</a>).</li></ul><p>Data is © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">OpenStreetMap contributors</a>, ODbL 1.0 — keep the attribution when you republish results.</p><h2 id="can-i-use-this-for-heavy-or-commercial-workloads" tabindex="-1">Can I use this for heavy or commercial workloads? <a class="header-anchor" href="#can-i-use-this-for-heavy-or-commercial-workloads" aria-label="Permalink to &quot;Can I use this for heavy or commercial workloads?&quot;">​</a></h2><p>Not against the public servers — self-host instead. Every backend has a <code>*_BASE_URL</code> variable and a well-documented self-hosting story: Nominatim, Photon, OSRM (run three instances behind <code>routed-*</code> prefixes), Overpass and Valhalla all ship Docker images. Point the variables at your instances and the same 11 tools run against infrastructure you own, with <code>OSM_CACHE_TTL=0</code> if your data changes often.</p><p>The middle ground is an <a href="https://openrouteservice.org" target="_blank" rel="noreferrer">OpenRouteService</a> key — see the next question.</p><h2 id="what-do-i-gain-from-an-ors-api-key" tabindex="-1">What do I gain from an <code>ORS_API_KEY</code>? <a class="header-anchor" href="#what-do-i-gain-from-an-ors-api-key" aria-label="Permalink to &quot;What do I gain from an `ORS_API_KEY`?&quot;">​</a></h2><p>A <strong>dedicated quota instead of shared best-effort capacity</strong>. With a key, <code>route</code>, <code>route_matrix</code> and <code>isochrone</code> switch to OpenRouteService (free tier: 2 000 directions/day, 40/minute, commercial plans above) — useful when the demo servers are busy, or when your usage is too steady to be a fair guest. Geocoding and POI search still use the public OSM services, and <code>optimize_route</code> stays on OSRM, which is the one engine with a native traveling-salesman service.</p><p>The key is the only secret this server can hold; see <a href="/guide/security#api-key-handling">Security</a> for how it is protected.</p><h2 id="everything-feels-slow-—-one-call-takes-several-seconds" tabindex="-1">Everything feels slow — one call takes several seconds <a class="header-anchor" href="#everything-feels-slow-—-one-call-takes-several-seconds" aria-label="Permalink to &quot;Everything feels slow — one call takes several seconds&quot;">​</a></h2><p>By design. The server throttles itself to ~1 request/second per service, and a single tool call can need several upstream requests: a 12-stop <code>optimize_route</code> geocodes 12 names before it can ask OSRM anything. Repeated questions are fast — identical requests come from the cache for <code>OSM_CACHE_TTL</code> seconds (default one hour).</p><p>If a call fails with <em>&quot;too many queued requests&quot;</em>, the per-service queue is full: batch fewer locations per call, or wait a moment.</p><h2 id="geocode-doesn-t-find-my-place" tabindex="-1"><code>geocode</code> doesn&#39;t find my place <a class="header-anchor" href="#geocode-doesn-t-find-my-place" aria-label="Permalink to &quot;`geocode` doesn&#39;t find my place&quot;">​</a></h2><ul><li>Try <code>provider: &quot;photon&quot;</code> — it is typo-tolerant and much better with partial or misspelled names.</li><li>Add context: &quot;Springfield, Illinois&quot; instead of &quot;Springfield&quot;.</li><li>Restrict the country: <code>countrycodes: &quot;de,lu&quot;</code> (Nominatim only).</li><li>For an address, Nominatim (the default) is usually the better provider.</li></ul><h2 id="find-nearby-pois-returns-nothing" tabindex="-1"><code>find_nearby_pois</code> returns nothing <a class="header-anchor" href="#find-nearby-pois-returns-nothing" aria-label="Permalink to &quot;`find_nearby_pois` returns nothing&quot;">​</a></h2><p>The category is a filter, not a search term. Use one of the built-in shortcuts (<code>restaurant</code>, <code>cafe</code>, <code>hotel</code>, <code>museum</code>, <code>viewpoint</code>, <code>supermarket</code>, <code>pharmacy</code>, <code>parking</code>, …) or a raw OSM tag as <code>key</code> or <code>key=value</code> — <code>&quot;diet:vegan=yes&quot;</code>, <code>&quot;amenity=library&quot;</code>. Then widen <code>radius_m</code> (default 1 000 m, max 10 000). Remember OSM only knows what mappers have tagged: no results can genuinely mean no tagged POIs there.</p><h2 id="route-matrix-rejects-my-call-with-too-many-locations" tabindex="-1"><code>route_matrix</code> rejects my call with &quot;too many locations&quot; <a class="header-anchor" href="#route-matrix-rejects-my-call-with-too-many-locations" aria-label="Permalink to &quot;`route_matrix` rejects my call with &quot;too many locations&quot;&quot;">​</a></h2><p>Origins + destinations must stay ≤ 25, to keep a single call inside the public OSRM usage policy. Split larger comparisons into several calls — the resolver cache means the geocoding cost is only paid once.</p><h2 id="overpass-answers-429-or-times-out" tabindex="-1">Overpass answers 429 or times out <a class="header-anchor" href="#overpass-answers-429-or-times-out" aria-label="Permalink to &quot;Overpass answers 429 or times out&quot;">​</a></h2><p>The public Overpass instance grants ~2 concurrent slots per IP and sheds load when busy. The server already retries on the configured mirror (<code>overpass.private.coffee</code> by default) before giving up; a persistent failure means both are busy. Wait, or configure your own mirror list via <code>OVERPASS_BASE_URL</code>.</p><h2 id="does-it-work-offline" tabindex="-1">Does it work offline? <a class="header-anchor" href="#does-it-work-offline" aria-label="Permalink to &quot;Does it work offline?&quot;">​</a></h2><p>Two tools do: <code>straight_line_distance</code> computes great-circle distance and <code>map_link</code> builds openstreetmap.org URLs — both offline once their inputs are literal <code>&quot;lat,lon&quot;</code> coordinates (place <em>names</em> still need geocoding). Everything else needs the network.</p><h2 id="can-it-edit-openstreetmap-render-maps-or-track-a-gps" tabindex="-1">Can it edit OpenStreetMap, render maps or track a GPS? <a class="header-anchor" href="#can-it-edit-openstreetmap-render-maps-or-track-a-gps" aria-label="Permalink to &quot;Can it edit OpenStreetMap, render maps or track a GPS?&quot;">​</a></h2><p>No, no and no. All tools are read-only against OSM (the editing API is not wired up at all), results are structured data plus links rather than images, and there is no state between calls. <code>map_link</code> gives you a URL to look at the map yourself.</p><h2 id="where-do-i-report-a-problem" tabindex="-1">Where do I report a problem? <a class="header-anchor" href="#where-do-i-report-a-problem" aria-label="Permalink to &quot;Where do I report a problem?&quot;">​</a></h2><ul><li>Questions and ideas → <a href="https://github.com/ni-c/osm-mcp/discussions" target="_blank" rel="noreferrer">Discussions</a></li><li>Reproducible problems → <a href="https://github.com/ni-c/osm-mcp/issues" target="_blank" rel="noreferrer">Issues</a></li><li>Vulnerabilities → <a href="https://github.com/ni-c/osm-mcp/security/advisories/new" target="_blank" rel="noreferrer">private reporting</a></li></ul>',36)])])}const m=o(s,[["render",i]]);export{p as __pageData,m as default};
